// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    // The owner (this test contract) must be able to receive the transferred ETH.
    receive() external payable {}

    function testFuzz_property(uint256 v) public {
        // Admissible domain: a nonzero, sane amount; the contract is dealt exactly
        // v wei so v is always <= balance (a legitimate reference state).
        v = bound(v, 1, type(uint128).max);
        vm.deal(address(c), v);

        bool ok;
        try c.withdraw(v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: the owner's withdraw actually transfers the requested value out
        // of the contract: the call succeeds and no ETH remains locked in c.
        assertTrue(ok && address(c).balance == 0);
    }
}
